css:
.bb-dccn { font-family: "Times New Roman", "Liberation Serif", Tinos, serif; font-size: 10.5pt; color: #000; line-height: 1.22; padding-right: 2.5%; }
.bb-dccn table { width: 100%; border-collapse: collapse; border: none; margin: 0; }
.bb-dccn td { border: none !important; padding: 0 2px !important; vertical-align: top !important; }
.bb-dccn .hdr td { font-size: 8.8pt; line-height: 1.3; }
.bb-dccn .hdr td.hdr-logo { width: 22%; vertical-align: middle !important; }
.bb-dccn .hdr .co-name { font-size: 12pt; font-weight: bold; }
.bb-dccn .logo { width: 100%; max-width: 148px; }
.bb-dccn .hdr-line { border-top: 1.5px solid #000; margin-top: 2px; }
.bb-dccn .docno { width: 30% !important; margin-left: 70% !important; }
.bb-dccn .docno td { font-size: 9.5pt; }
.bb-dccn .docno td.k { width: 18%; }
.bb-dccn .title { text-align: center; font-size: 15pt; font-weight: bold; margin: 3px 0 3px; }
.bb-dccn .basis { font-style: italic; }
.bb-dccn .gap { margin-top: 3px; }
.bb-dccn .sec { font-weight: bold; margin-top: 3px; }
.bb-dccn .party { margin-top: 3px; }
.bb-dccn .party td.lbl { width: 24%; }
.bb-dccn .party td.lbl.sub { padding-left: 3% !important; }
.bb-dccn .party td.val { width: 46%; }
.bb-dccn .party td.mst { font-weight: bold; text-align: right; }
.bb-dccn .party td.tel { padding-left: 1.2% !important; }
.bb-dccn .agree { font-weight: bold; font-style: italic; text-align: center; margin-top: 4px; }
.bb-dccn .fig td { vertical-align: middle !important; }
.bb-dccn .fig td.lbl { width: 36%; padding-left: 4% !important; }
.bb-dccn .fig td.lbl0 { width: 36%; }
.bb-dccn .fig td.sub { font-style: italic; padding-left: 7% !important; }
.bb-dccn .fig td.colon { width: 2%; }
.bb-dccn .fig td.amt { width: 20%; text-align: right; }
.bb-dccn .fig td.unit { width: 8%; padding-left: 8px !important; }
.bb-dccn .b { font-weight: bold; }
.bb-dccn .bi { font-weight: bold; font-style: italic; }
.bb-dccn .addr { padding-left: 7%; font-weight: bold; font-style: italic; }
.bb-dccn .sign { margin-top: 5px; border-top: 1px solid #000 !important; page-break-inside: avoid; }
.bb-dccn .sign td { text-align: center; width: 50%; }
.bb-dccn .sign td.l { border-right: 1px solid #000 !important; }
.bb-dccn .sign .note { font-style: italic; font-size: 9pt; }

html:
{%- macro money(v) -%}{{ "{:,.0f}".format((v or 0)|float|abs).replace(",", ".") }}{%- endmacro -%}
{%- macro dmy(d) -%}{{ frappe.utils.formatdate(d, "dd/MM/yyyy") if d else "…" }}{%- endmacro -%}
{%- macro bal_label(direction, suffix) -%}{% if direction == "Dư Có" %}Dư có {{ suffix }}{% elif direction == "Dư Nợ" %}Dư nợ {{ suffix }}{% else %}Dư nợ/có {{ suffix }}{% endif %}{%- endmacro -%}
{%- set is_supplier = true -%}
{%- set s = frappe.get_cached_doc("Debt Reconciliation Settings") -%}
{%- set co = frappe.db.get_value("Company", doc.company, ["company_name", "tax_id", "company_logo"], as_dict=True) or {} -%}
{%- set co_name = s.company_legal_name or co.company_name or doc.company -%}
{%- set co_tax = co.tax_id or s.company_tax_id or "…" -%}
{%- set co_addr = s.company_address or "…" -%}
{%- set logo = co.company_logo or "/assets/erpnext/images/miyano-logo-wide.jpg" -%}
{%- set p_name = doc.party_name or doc.party -%}
{%- set pd = frappe.utils.getdate(doc.posting_date) -%}
{%- set owed_dir = "Dư Có" if is_supplier else "Dư Nợ" -%}
<div class="bb-dccn">
<table class="hdr"><tr>
<td class="hdr-logo"><img class="logo" src="{{ logo }}"></td>
<td>
<div class="co-name">{{ co_name }}</div>
<div>Trụ sở: {{ co_addr }}</div>
{% if s.hard_copy_address %}<div>VPGD: {{ s.hard_copy_address }}</div>{% endif %}
<div>Tel: {{ s.company_phone or "…" }}</div>
<table><tr><td style="width:50%; padding:0 !important;">Mã số thuế: {{ co_tax }}</td><td style="padding:0 !important;">{% if s.company_email %}Email: {{ s.company_email }}{% endif %}</td></tr></table>
</td></tr></table>
<div class="hdr-line"></div>
<table class="docno"><tr><td class="k">Số:</td><td>{{ doc.statement_no }}</td></tr>
<tr><td class="k">Ngày</td><td>{{ dmy(doc.posting_date) }}</td></tr></table>

<div class="title">BIÊN BẢN ĐỐI CHIẾU &amp; XÁC NHẬN CÔNG NỢ</div>

<div class="basis">- Căn cứ vào Hợp đồng nguyên tắc số {{ doc.framework_contract_no or "…....." }} ngày {{ dmy(doc.framework_contract_date) if doc.framework_contract_date else "…......" }} ký giữa {{ co_name }}</div>
<div class="basis">và {{ p_name }}</div>
<div class="basis">- Căn cứ vào thực hiện các giao dịch thương mại và mua bán giữa các bên sau đây.</div>
<div class="gap">Hôm nay, ngày {{ "%02d"|format(pd.day) }} tháng {{ "%02d"|format(pd.month) }} năm {{ pd.year }}, tại Hà Nội. Chúng tôi gồm có:</div>

{%- macro party_block(title, name, tax, addr_label, addr, phone, rep, rep_title) -%}
<table class="party">
<tr><td class="lbl b">{{ title }}</td><td class="val b">: {{ name }}</td><td class="mst">MST: {{ tax or "…..............." }}</td></tr>
<tr><td class="lbl sub">{{ addr_label }}</td><td colspan="2">: {{ addr or "…........................................................................................" }}</td></tr>
<tr><td class="lbl"></td><td colspan="2" class="tel">Tel: {{ phone or "(+84)" }}</td></tr>
<tr><td class="lbl sub">1. Đại diện Ông (bà)</td><td class="val">: {{ rep or "" }}</td><td>Chức vụ: {{ rep_title or "" }}</td></tr>
<tr><td class="lbl sub">2. Đại diện Ông (bà)</td><td class="val">:</td><td>Chức vụ:</td></tr>
</table>
{%- endmacro -%}

{%- set miyano = [co_name, co_tax, "Địa chỉ", co_addr, s.company_phone, doc.company_representative, doc.company_representative_title] -%}
{%- set partner = [p_name, doc.party_tax_id, "Trụ sở giao dịch", doc.party_address, doc.party_phone, doc.party_representative, doc.party_representative_title] -%}
{%- set side_a = partner if is_supplier else miyano -%}
{%- set side_b = miyano if is_supplier else partner -%}
{{ party_block("I. Bên bán (Bên A)", *side_a) }}
{{ party_block("II. Bên mua (Bên B)", *side_b) }}

<div class="agree">Hai bên cùng nhau thống nhất đối chiếu và xác nhận công nợ từ ngày {{ dmy(doc.from_date) }} đến ngày {{ dmy(doc.to_date) }}, nội dung như sau:</div>

<div class="sec">[i] SỐ DƯ ĐẦU KỲ</div>
<table class="fig">
<tr><td class="lbl b">{{ bal_label(doc.opening_direction, "đầu kỳ") }}</td><td class="colon">:</td><td class="amt b">{{ money(doc.opening_principal + doc.opening_interest) }}</td><td class="unit b">Đồng</td><td></td></tr>
<tr><td class="lbl bi">Gồm:</td><td></td><td></td><td></td><td></td></tr>
<tr><td class="lbl sub">(1) Giá trị gốc</td><td class="colon">:</td><td class="amt">{{ money(doc.opening_principal) }}</td><td class="unit">Đồng</td><td></td></tr>
<tr><td class="lbl sub">(2) Lãi quá hạn</td><td class="colon">:</td><td class="amt">{{ money(doc.opening_interest) }}</td><td class="unit">Đồng</td><td></td></tr>
</table>

<div class="sec">[ii] SỐ PHÁT SINH TRONG KỲ</div>
<table class="fig">
<tr><td class="lbl b">1. Phát sinh có trong kỳ</td><td class="colon">:</td><td class="amt b">{{ money(doc.credit_in_period + doc.interest_in_period) }}</td><td class="unit b">Đồng</td><td></td></tr>
<tr><td class="lbl sub">(1) Giá trị gốc</td><td class="colon">:</td><td class="amt">{{ money(doc.credit_in_period) }}</td><td class="unit">Đồng</td><td></td></tr>
<tr><td class="lbl sub">(2) Lãi quá hạn</td><td class="colon">:</td><td class="amt">{{ money(doc.interest_in_period) }}</td><td class="unit">Đồng</td><td></td></tr>
<tr><td class="lbl b">2. Phát sinh nợ trong kỳ</td><td class="colon b">:</td><td class="amt b">{{ money(doc.debit_in_period) }}</td><td class="unit b">Đồng</td><td></td></tr>
</table>

<div class="sec">[iii] SỐ DƯ CUỐI KỲ</div>
<table class="fig">
<tr><td class="lbl b">{{ bal_label(doc.balance_direction, "cuối kỳ") }}</td><td class="colon">:</td><td class="amt b">{{ money(doc.closing_balance) }}</td><td class="unit b">Đồng</td><td></td></tr>
</table>

<div class="sec">[iv] KẾT LUẬN:</div>
{%- set debtor = co_name if is_supplier else p_name -%}
{%- set creditor = p_name if is_supplier else co_name -%}
<div>Tính đến hết ngày {{ dmy(doc.to_date) }},
{% if doc.balance_direction == "Bằng 0" -%}
{{ co_name }} và {{ p_name }} không còn công nợ, số tiền là:
{%- elif doc.balance_direction == owed_dir -%}
{{ debtor }} còn nợ tiền mua hàng của {{ creditor }} là:
{%- else -%}
{{ debtor }} đã thanh toán trước cho {{ creditor }} là:
{%- endif %}</div>
<table class="fig">
<tr><td class="lbl0">Tổng số tiền bằng số</td><td class="colon">:</td><td class="amt b">{{ money(doc.closing_balance) }}</td><td class="unit">Đồng</td><td></td></tr>
<tr><td class="lbl0">Tổng số tiền bằng chữ</td><td class="colon">:</td><td colspan="3" class="bi">{{ so_thanh_chu(doc.closing_balance|float|abs) }} ./.</td></tr>
</table>

<div class="gap">Rất mong Quý công ty ký, đóng dấu xác nhận công nợ và gửi về {{ co_name }} trước ngày {{ dmy(doc.response_deadline) }}.</div>
<div>Theo địa chỉ VPGD của Công ty chúng tôi:</div>
<div class="addr">{{ co_name }}</div>
<div class="addr">{{ s.hard_copy_address or "" }}</div>
{% if s.contact_line %}<div class="addr">Liên hệ: {{ s.contact_line }}</div>{% endif %}

<div class="gap">Biên bản này được lập thành 02 bản, mỗi bên giữ 01 bản và có giá trị pháp lý như nhau./.</div>

<table class="sign">
<tr><td class="l b">ĐẠI DIỆN BÊN A (BÊN BÁN)</td><td class="b">ĐẠI DIỆN BÊN B (BÊN MUA)</td></tr>
<tr><td class="l note">(Ký, đóng dấu và ghi rõ họ tên)</td><td class="note">(Ký, đóng dấu và ghi rõ họ tên)</td></tr>
<tr><td class="l" style="height:62px;"></td><td></td></tr>
</table>
</div>
